import { DatePickerInput } from '@mantine/dates';
import { isInSeries } from './recurrence';
import type { RecurringEventFormType } from './types';
import { useSeries } from './use-series';

export function ExceptionsInput({ form }: { form: RecurringEventFormType }) {
  const { start, recurrence, complete } = useSeries(form);

  return (
    <DatePickerInput
      type="multiple"
      valueDisplay="pills"
      valueFormat="MMM D, YYYY"
      label="Exceptions"
      placeholder="Pick dates to skip"
      minDate={start?.slice(0, 10)}
      defaultDate={start?.slice(0, 10)}
      excludeDate={(date) => !complete || !start || !isInSeries(start, recurrence, date)}
      {...form.getInputProps('exceptions')}
    />
  );
}

import { NumberInput, Text } from '@mantine/core';
import type { Frequency, RecurringEventFormType } from './types';
import { INTERVAL_LIMITS, INTERVAL_UNITS } from './validation';

export function IntervalInput({
  form,
  frequency,
}: {
  form: RecurringEventFormType;
  frequency: Frequency;
}) {
  const interval = form.useWatchValue('interval');
  const [singular, plural] = INTERVAL_UNITS[frequency];

  return (
    <NumberInput
      label="Repeat every"
      placeholder="1"
      min={INTERVAL_LIMITS.min}
      max={INTERVAL_LIMITS.max}
      allowNegative={false}
      allowDecimal={false}
      hideControls
      maw={240}
      rightSection={<Text size="sm">{Number(interval) === 1 ? singular : plural}</Text>}
      rightSectionWidth={72}
      rightSectionPointerEvents="none"
      withAsterisk
      {...form.getInputProps('interval')}
    />
  );
}

import { Radio, Stack } from '@mantine/core';
import { describeMonthlyRule, getMonthlyRule } from './recurrence';
import type { MonthlyBy, RecurringEventFormType } from './types';

const FALLBACK_LABELS: Record<MonthlyBy, string> = {
  dayOfMonth: 'The same day of the month',
  weekdayOfMonth: 'The same weekday of the month',
};

export function MonthlyOptions({ form }: { form: RecurringEventFormType }) {
  const start = form.useWatchValue('start');
  const label = (by: MonthlyBy) =>
    start ? describeMonthlyRule(getMonthlyRule(start, by)) : FALLBACK_LABELS[by];

  return (
    <Radio.Group label="Repeat on" {...form.getInputProps('monthlyBy')}>
      <Stack gap="xs" mt="xs">
        <Radio value="dayOfMonth" label={label('dayOfMonth')} />
        <Radio value="weekdayOfMonth" label={label('weekdayOfMonth')} />
      </Stack>
    </Radio.Group>
  );
}

import { Input, List, Text } from '@mantine/core';
import { formatOccurrence, getOccurrences } from './recurrence';
import type { RecurringEventFormType } from './types';
import { useSeries } from './use-series';

const PREVIEW_SIZE = 5;

function PreviewContent({ form }: { form: RecurringEventFormType }) {
  const { start, allDay, exceptions, recurrence, complete } = useSeries(form);

  if (!start) {
    return <Text size="sm">Set the start to see the occurrences</Text>;
  }

  if (!complete) {
    return <Text size="sm">Complete the recurrence to see the occurrences</Text>;
  }

  const occurrences = getOccurrences(start, recurrence, recurrence ? exceptions : [], PREVIEW_SIZE);

  if (occurrences.length === 0) {
    return <Text size="sm">No occurrences</Text>;
  }

  return (
    <List size="sm" aria-label="Next occurrences">
      {occurrences.map((date) => (
        <List.Item key={date}>{formatOccurrence(date, start, allDay)}</List.Item>
      ))}
    </List>
  );
}

export function OccurrencesPreview({ form }: { form: RecurringEventFormType }) {
  return (
    <div>
      <Input.Label labelElement="div">Next occurrences</Input.Label>
      <PreviewContent form={form} />
    </div>
  );
}

import { Radio, Stack, Title } from '@mantine/core';
import { EndsFields } from './EndsFields';
import { ExceptionsInput } from './ExceptionsInput';
import { IntervalInput } from './IntervalInput';
import { MonthlyOptions } from './MonthlyOptions';
import { OccurrencesPreview } from './OccurrencesPreview';
import type { RecurringEventFormType } from './types';
import { REPEAT_OPTIONS } from './validation';
import { WeekdaysInput } from './WeekdaysInput/WeekdaysInput';

export function RecurrenceFields({ form }: { form: RecurringEventFormType }) {
  const repeat = form.useWatchValue('repeat');

  return (
    <Stack>
      <Title order={3} c="var(--mantine-color-bright)">
        Recurrence
      </Title>

      <Stack gap="xs">
        <Radio.Group label="Repeat" {...form.getInputProps('repeat')}>
          <Stack gap="xs" mt="xs">
            {REPEAT_OPTIONS.map((option) => (
              <Radio key={option.value} value={option.value} label={option.label} />
            ))}
          </Stack>
        </Radio.Group>

        {repeat !== 'none' && <IntervalInput form={form} frequency={repeat} />}
        {repeat === 'weekly' && <WeekdaysInput form={form} />}
